RA='رضی اللہ عنہ'
def uhud_map(w,h,title,labels,cap):
    b=f'<rect x="5" y="5" width="{w-10}" height="{h-10}" fill="#fff" stroke="#111" stroke-width="2"/>'+T(w/2,30,title,18,'middle',700)
    b+='<path d="M150 70 Q220 50 300 90 Q340 130 280 160 Q200 150 150 70Z" fill="#d9d0b8" stroke="#555" stroke-width="2"/>'
    b+='<ellipse cx="330" cy="260" rx="70" ry="55" fill="#e9e1c8" stroke="#555" stroke-dasharray="3 3"/>'
    b+='<path d="M90 120 Q130 220 140 320 Q150 380 200 400" fill="none" stroke="#111" stroke-width="3" stroke-dasharray="8 4"/>'
    b+='<path d="M170 410 Q175 340 260 320" fill="none" stroke="#111" stroke-width="3" stroke-dasharray="3 3"/>'
    b+='<g stroke="#2a6" stroke-width="2"><line x1="210" y1="220" x2="210" y2="238"/><line x1="230" y1="235" x2="230" y2="253"/><line x1="250" y1="250" x2="250" y2="268"/></g>'
    for x,y,t in labels: b+=T(x,y,t,12,'middle',700)
    b+='<line x1="30" y1="'+str(h-30)+'" x2="130" y2="'+str(h-30)+'" stroke="#111" stroke-width="2"/>'+T(80,h-14,'میل',11,'middle',700)
    return svg(w,h,cap,b)
def plan_map(w,h,title,labels,cap):
    b=f'<rect x="5" y="5" width="{w-10}" height="{h-10}" fill="#fff" stroke="#111" stroke-width="2"/>'+T(w/2,28,title,16,'middle',700)
    b+='<path d="M20 90 Q120 40 220 70 Q320 40 420 100" fill="none" stroke="#555" stroke-width="6" stroke-dasharray="2 2"/>'
    b+='<path d="M330 120 Q400 150 410 260 Q400 300 340 280Z" fill="#e0d8c0" stroke="#555"/>'
    b+='<line x1="10" y1="300" x2="'+str(w-10)+'" y2="300" stroke="#111" stroke-width="2"/>'
    b+='<rect x="200" y="210" width="40" height="30" fill="none" stroke="#111" stroke-width="2"/><rect x="150" y="190" width="14" height="12" fill="none" stroke="#111"/><rect x="260" y="180" width="14" height="12" fill="none" stroke="#111"/>'
    b+='<ellipse cx="170" cy="345" rx="60" ry="12" fill="#ddd" stroke="#555"/>'
    b+='<path d="M120 120 Q100 180 130 250" fill="none" stroke="#111" stroke-width="2"/><path d="M360 330 L330 305" fill="none" stroke="#111" stroke-width="2"/>'
    for x,y,t in labels: b+=T(x,y,t,11,'middle',700)
    return svg(w,h,cap,b)
